        body += '<line x1="' + (cyx - crx) + '" y1="' + cyTop + '" x2="' + (cyx - crx) + '" y2="' + (cyTop + cyH) + '" stroke="#0284c7" stroke-width="2"/>';
        body += '<line x1="' + (cyx + crx) + '" y1="' + cyTop + '" x2="' + (cyx + crx) + '" y2="' + (cyTop + cyH) + '" stroke="#0284c7" stroke-width="2"/>';
