        body += '<line x1="' + cApexX + '" y1="' + cApexY + '" x2="' + (cApexX - cRadX) + '" y2="' + cBaseY + '" stroke="#7c3aed" stroke-width="2"/>';
        body += '<line x1="' + cApexX + '" y1="' + cApexY + '" x2="' + (cApexX + cRadX) + '" y2="' + cBaseY + '" stroke="#7c3aed" stroke-width="2"/>';
