  function g11ScFunctionGraphs(A) {
    var K = kit(A), T = K.T, shape = K.shape, page = K.page, S = K.S, line = K.line, step = K.step,
        title = K.title, card = K.card, kids = K.kids;
    var sec = function (text, y) { return title(text, { x: 60, y: y || 100, size: 34, color: 'brand' }); };
    var R = String.raw;

    var slides = [
      /* 1 Cover */ S.cover('==គណិតវិទ្យា== ថ្នាក់ទី១១ (វិទ្យាសាស្ត្រ)', 'ជំពូកទី ៥ · មេរៀនទី ៣', 'អថេរភាព និងក្រាបនៃអនុគមន៍ (Variation & Graphs)', K.info),

      /* 2 TOC */ K.toc([
        '==១. អថេរភាព & ក្រាបអនុគមន៍ដឺក្រេទី ៣==',
        '២. ភាពប៉ោង ផត និងចំណុចរបត់',
        '==៣. អថេរភាព & ក្រាបអនុគមន៍ប៊ីការ៉េ==',
        '៤. អាស៊ីមតូតឈរ និងអាស៊ីមតូតដេក',
        '==៥. អថេរភាព & ក្រាបអនុគមន៍សនិទាន==',
        '៦. សង្ខេបវិធាន & រូបមន្តគន្លឹះមេរៀនទី ១៩',
        '==៧. សំណួរពហុជ្រើសរើស (MCQ 1 & 2)==',
        '៨. កិច្ចការផ្ទះ & អនុវត្តន៍'
      ], 32),

      /* 3 Objective */ S.objective([
        'ចេះសិក្សាអថេរភាព សង់តារាងអថេរភាព រកចំណុចរបត់ និងសង់ក្រាបនៃអនុគមន៍ពហុធាដឺក្រេទី ៣ និងប៊ីការ៉េ',
        'ចេះកំណត់អាស៊ីមតូតឈរ អាស៊ីមតូតដេក ផ្ចិតឆ្លុះ និងសង់ក្រាបនៃអនុគមន៍សនិទាន $y = \\frac{ax+b}{cx+d}$ បានត្រឹមត្រូវ'
      ], 'ក្រាបនៃអនុគមន៍ផ្តល់នូវរូបភាពច្បាស់លាស់ពីដំណើរប្រែប្រួលនៃបាតុភូតរូបវិទ្យា សេដ្ឋកិច្ច និងវិស្វកម្ម!'),

      /* 4 Cubic Polynomial */ page([
        sec('១. អថេរភាព & ក្រាបអនុគមន៍ដឺក្រេទី ៣'),
        card(60, 155, 560, 375, 'ទម្រង់ទូទៅ $y = ax^3 + bx^2 + cx + d$', R`• **ជំហានសិក្សា ៖**
  1. ដែនកំណត់ ៖ $D = \mathbb{R}$
  2. ដេរីវេ ៖ $y' = 3ax^2 + 2bx + c$
     - $\Delta' > 0$ ៖ $y' = 0$ មានឫសពីរ $\implies$ មានបរមាធៀប ២
     - $\Delta' \le 0$ ៖ គ្មានបរមាធៀបទេ (អនុគមន៍កើន ឬចុះជានិច្ច)
  3. លីមីតចុងដែន ៖ គណនា $\lim_{x \to \pm\infty} y$
  4. តារាងអថេរភាព & សង់ក្រាប`, { size: 17.5 }),
        card(660, 155, 560, 375, 'លំហាត់គំរូ ៖ អនុគមន៍ដឺក្រេទី ៣', R`• **ប្រធាន ៖** សិក្សាអថេរភាព $f(x) = x^3 - 3x^2 + 2$
• **ដំណោះស្រាយ ៖**
  - $D = \mathbb{R}$
  - $f'(x) = 3x^2 - 6x = 3x(x - 2)$
  - $f'(x) = 0 \iff x = 0$ ឬ $x = 2$
  - អតិបរមាធៀប ៖ $f(0) = 2$
  - អប្បបរមាធៀប ៖ $f(2) = 2^3 - 3(2^2) + 2 = -2$
  - លីមីត ៖ $\lim_{x \to -\infty} f = -\infty$, $\lim_{x \to +\infty} f = +\infty$`, { size: 17.5 }),
        S.box(60, 545, 1160, 80, R`ចំណាំ ៖ មេគុណ $a > 0$ ក្រាបឡើងនៅខាងស្តាំ ($+\infty$); បើ $a < 0$ ក្រាបចុះនៅខាងស្តាំ ($-\infty$)!`)
      ]),

      /* 5 Concavity & Inflection Point */ page([
        sec('២. ភាពប៉ោង ផត និងចំណុចរបត់'),
        card(60, 155, 560, 375, 'ដេរីវេទីពីរ $y\'\'$ & ចំណុចរបត់', R`• **លក្ខណៈភាពប៉ោង-ផត ៖**
  - បើ $y'' > 0$ លើចន្លោះ $I \implies$ ក្រាប**ផត** (Concave up $\cup$)
  - បើ $y'' < 0$ លើចន្លោះ $I \implies$ ក្រាប**ប៉ោង** (Concave down $\cap$)
• **ចំណុចរបត់ (Inflection Point) ៖**
  - ជាចំណុចដែលក្រាបផ្លាស់ប្តូរពីប៉ោងទៅផត ឬពីផតទៅប៉ោង
  - លក្ខខណ្ឌ ៖ $y'' = 0$ ហើយប្តូរសញ្ញាសងខាង $x_0$
  - ចំពោះដឺក្រេទី ៣ ៖ អាប់ស៊ីសរបត់គឺ $x_0 = -\frac{b}{3a}$`, { size: 17.5 }),
        card(660, 155, 560, 375, 'លំហាត់គំរូ ៖ រកចំណុចរបត់', R`• **អនុវត្តលើ $f(x) = x^3 - 3x^2 + 2$ ៖**
  - $f'(x) = 3x^2 - 6x$
  - $f''(x) = 6x - 6$
  - $f''(x) = 0 \iff 6x - 6 = 0 \implies x_0 = 1$
  - $y_0 = f(1) = 1 - 3 + 2 = 0$
  - ចំណុចរបត់ ៖ $I(1, 0)$
  - សមីការបន្ទាត់ប៉ះត្រង់ $I$ ៖
    $$y = f'(1)(x - 1) + 0 = -3(x - 1) = -3x + 3$$`, { size: 17.5 }),
        S.box(60, 545, 1160, 80, R`ទ្រឹស្តីបទសំខាន់ ៖ ចំណុចរបត់ $I$ នៃអនុគមន៍ដឺក្រេទី ៣ គឺជា**ផ្ចិតឆ្លុះ**នៃក្រាបជានិច្ច!`)
      ]),

      /* 6 Biquadratic Function */ page([
        sec('៣. អថេរភាព & ក្រាបអនុគមន៍ប៊ីការ៉េ'),
        card(60, 155, 560, 375, 'ទម្រង់ទូទៅ $y = ax^4 + bx^2 + c$', R`• **លក្ខណៈទូទៅ ៖**
  - ជាអនុគមន៍គូ ៖ ក្រាបឆ្លុះគ្នាធៀបនឹងអ័ក្សអរដោនេ $(y'Oy)$
  - ដេរីវេ ៖ $y' = 4ax^3 + 2bx = 2x(2ax^2 + b)$
• **ករណីបរមាធៀប ៖**
  - បើ $ab < 0$ ៖ $y' = 0$ មានឫស ៣ គឺ $x = 0, \pm\sqrt{-\frac{b}{2a}}$
    $\implies$ ក្រាបមានរាងអក្សរ **W** (បើ $a>0$) ឬ **M** (បើ $a<0$)
  - បើ $ab \ge 0$ ៖ $y' = 0$ មានឫសតែមួយ $x = 0$
    $\implies$ ក្រាបមានរាងដូចប៉ារ៉ាបូល **U**`, { size: 17.5 }),
        card(660, 155, 560, 375, 'លំហាត់គំរូ ៖ អនុគមន៍ប៊ីការ៉េ', R`• **ប្រធាន ៖** សិក្សាអថេរភាព $y = x^4 - 2x^2 - 3$
• **ដំណោះស្រាយ ៖**
  - $D = \mathbb{R}$ ; ជាអនុគមន៍គូ
  - $y' = 4x^3 - 4x = 4x(x^2 - 1)$
  - $y' = 0 \iff x = 0, x = 1, x = -1$
  - តម្លៃបរមាធៀប ៖
    $$x = 0 \implies y = -3 \quad (\text{អតិបរមាធៀប})$$
    $$x = \pm 1 \implies y = -4 \quad (\text{អប្បបរមាធៀប})$$
  - ក្រាបមានរាងអក្សរ W ឆ្លុះធៀបនឹងអ័ក្ស $Oy$`, { size: 17.5 }),
        S.box(60, 545, 1160, 80, R`គន្លឹះ ៖ ពិនិត្យសញ្ញាផលគុណ $a \times b$ ៖ បើ $ab < 0$ មានកំពូល ៣; បើ $ab \ge 0$ មានកំពូលតែ ១!`)
      ]),

      /* 7 Rational Function */ page([
        sec('៤. អាស៊ីមតូត & អនុគមន៍សនិទាន'),
        card(60, 155, 560, 375, 'អនុគមន៍សនិទាន $y = \\frac{ax+b}{cx+d}$', R`• **លក្ខណៈគ្រឹះ ($c \neq 0, ad - bc \neq 0$) ៖**
  - ដែនកំណត់ ៖ $D = \mathbb{R} \setminus \{-\frac{d}{c}\}$
  - **អាស៊ីមតូតឈរ ៖** បន្ទាត់ $x = -\frac{d}{c}$
  - **អាស៊ីមតូតដេក ៖** បន្ទាត់ $y = \frac{a}{c}$
• **ទិសដៅអថេរភាព ៖**
  - ដេរីវេ ៖ $y' = \frac{ad - bc}{(cx + d)^2}$
  - បើ $ad - bc > 0 \implies y' > 0$ (កើនជានិច្ច)
  - បើ $ad - bc < 0 \implies y' < 0$ (ចុះជានិច្ច)`, { size: 18 }),
        card(660, 155, 560, 375, 'លំហាត់គំរូ ៖ អនុគមន៍សនិទាន', R`• **ប្រធាន ៖** សិក្សា $y = \frac{2x - 1}{x + 1}$
• **ដំណោះស្រាយ ៖**
  - ដែនកំណត់ ៖ $D = \mathbb{R} \setminus \{-1\}$
  - អាស៊ីមតូតឈរ ៖ $x = -1$ (ព្រោះ $\lim_{x \to -1} y = \infty$)
  - អាស៊ីមតូតដេក ៖ $y = \frac{2}{1} = 2$ (ព្រោះ $\lim_{x \to \pm\infty} y = 2$)
  - ដេរីវេ ៖ $y' = \frac{2(1) - (-1)(1)}{(x + 1)^2} = \frac{3}{(x + 1)^2} > 0$
  - អនុគមន៍កើនជានិច្ចលើ $(-\infty, -1)$ និង $(-1, +\infty)$
  - ផ្ចិតឆ្លុះ ៖ ប្រសព្វអាស៊ីមតូត $I(-1, 2)$`, { size: 17 }),
        S.box(60, 545, 1160, 80, R`ចងចាំ ៖ ចំណុចប្រសព្វរវាងអាស៊ីមតូតឈរ និងអាស៊ីមតូតដេក $I(-\frac{d}{c}, \frac{a}{c})$ ជា**ផ្ចិតឆ្លុះ**នៃក្រាបអ៊ីពែបូល!`)
      ]),

      /* 8 Summary */ page([
        sec('សង្ខេបវិធាន & រូបមន្តគន្លឹះមេរៀនទី ១៩'),
        card(60, 155, 560, 375, 'ពហុធាដឺក្រេទី ៣ & ប៊ីការ៉េ', R`• **ដឺក្រេទី ៣ ៖**
  - $y = ax^3 + bx^2 + cx + d$
  - ចំណុចរបត់ $x_0 = -\frac{b}{3a}$ ជាផ្ចិតឆ្លុះ
  - មានបរមាធៀប ២ កាលណា $y' = 0$ មានឫស ២
• **ប៊ីការ៉េ ៖**
  - $y = ax^4 + bx^2 + c$ ជាអនុគមន៍គូ
  - $ab < 0 \implies 3$ បរមាធៀប (W ឬ M)
  - $ab \ge 0 \implies 1$ បរមាធៀប (U)`, { size: 18 }),
        card(660, 155, 560, 375, 'អនុគមន៍សនិទាន $y = \\frac{ax+b}{cx+d}$', R`• **អាស៊ីមតូត ៖**
  - ឈរ ៖ $x = -\frac{d}{c}$
  - ដេក ៖ $y = \frac{a}{c}$
  - ផ្ចិតឆ្លុះ ៖ $I\left(-\frac{d}{c}, \frac{a}{c}\right)$
• **ដេរីវេ ៖**
  - $y' = \frac{ad - bc}{(cx + d)^2}$
  - គ្មានបរមាធៀបទេ (កើនរហូត ឬចុះរហូត)`, { size: 18 }),
        S.box(60, 545, 1160, 80, R`បាវចនា ៖ ពីដេរីវេទី ១ យើងស្គាល់ទិសដៅអថេរភាព ពីដេរីវេទី ២ យើងស្គាល់ភាពប៉ោង-ផត និងចំណុចរបត់!`)
      ]),

      /* 9 MCQ 1 */ page([
        sec('សំណួរពហុជ្រើសរើស (MCQ) - សំណួរទី ១'),
        card(60, 155, 560, 375, 'សំណួរទី ១', R`**ក្រាបនៃអនុគមន៍សនិទាន $y = \dfrac{3x - 5}{x + 2}$ មានអាស៊ីមតូតឈរ និងអាស៊ីមតូតដេកជាបន្ទាត់ ៖**

• **ក.** $x = 2$ និង $y = 3$
• **ខ.** $x = -2$ និង $y = 3$ *(ចម្លើយត្រឹមត្រូវ)*
• **គ.** $x = -2$ និង $y = -5$
• **ឃ.** $x = 3$ និង $y = -2$`, { size: 19 }),
        card(660, 155, 560, 375, 'ការពន្យល់ និងដំណោះស្រាយ', R`• **អាស៊ីមតូតឈរ ៖**
  - ឲ្យភាគបែងស្មើ $0$ ៖ $x + 2 = 0 \implies x = -2$
• **អាស៊ីមតូតដេក ៖**
  - យកផលធៀបមេគុណ $x$ ៖ $y = \frac{3}{1} = 3$
• **សេចក្តីសន្និដ្ឋាន ៖ ខ ជាចម្លើយត្រឹមត្រូវ**`, { size: 18.5 }),
        S.box(60, 545, 1160, 80, R`គន្លឹះ MCQ ៖ អាស៊ីមតូតឈរគឺឫសភាគបែង ($x=-2$) ឯអាស៊ីមតូតដេកគឺមេគុណ $x$ លើគ្នា ($y=3$)!`, { bg: '#ecfdf5', border: '#10b981', color: '#065f46' })
      ]),

      /* 10 MCQ 2 */ page([
        sec('សំណួរពហុជ្រើសរើស (MCQ) - សំណួរទី ២'),
        card(60, 155, 560, 375, 'សំណួរទី ២', R`**អនុគមន៍ប៊ីការ៉េ $y = x^4 - 4x^2 + 1$ មានចំនួនចំណុចបរមាធៀបសរុបស្មើនឹង ៖**

• **ក.** $1$
• **ខ.** $2$
• **គ.** $3$ *(ចម្លើយត្រឹមត្រូវ)*
• **ឃ.** $4$`, { size: 19 }),
        card(660, 155, 560, 375, 'ការពន្យល់ និងដំណោះស្រាយ', R`• **ពិនិត្យមេគុណ $a$ និង $b$ ៖**
  - $a = 1 > 0$ និង $b = -4 < 0$
  - ផលគុណ $ab = 1 \times (-4) = -4 < 0$
• **ដេរីវេ ៖**
  - $y' = 4x^3 - 8x = 4x(x^2 - 2) = 0$
  - ផ្តល់ឫស ៣ ផ្សេងគ្នា ៖ $x = 0, x = \pm\sqrt{2}$
• **សេចក្តីសន្និដ្ឋាន ៖ គ ជាចម្លើយត្រឹមត្រូវ**`, { size: 18.5 }),
        S.box(60, 545, 1160, 80, R`គន្លឹះ ៖ ដោយ $ab < 0$ នាំឱ្យក្រាបមានរាងជាអក្សរ W ដែលមានចំណុចបរមាធៀបចំនួន ៣!`, { bg: '#ecfdf5', border: '#10b981', color: '#065f46' })
      ]),

      /* 11 Homework */ S.homework([
        'សិក្សាអថេរភាព និងសង់ក្រាបនៃអនុគមន៍ f(x) = -x³ + 3x + 2 រួចរកចំណុចរបត់ និងផ្ចិតឆ្លុះ',
        'សិក្សាអថេរភាព និងសង់ក្រាបនៃអនុគមន៍ប៊ីការ៉េ y = x⁴ - 2x² - 3',
        'រកអាស៊ីមតូតឈរ អាស៊ីមតូតដេក និងសង់ក្រាបនៃអនុគមន៍សនិទាន y = (2x + 1)/(x - 1)',
        'កំណត់តម្លៃ m ដើម្បីឱ្យអនុគមន៍ y = x³ - 3mx² + 3x - 1 កើនជានិច្ចលើ ℝ',
        'សរសេរសមីការបន្ទាត់ប៉ះនឹងក្រាប y = x³ - 3x² + 2 ត្រង់ចំណុចរបត់របស់វា'
      ], 'កិច្ចការផ្ទះ ៖ ថ្នាក់ទី ១១ វិទ្យាសាស្ត្រ · ជំពូកទី ៥ មេរៀនទី ៣ (សៀវភៅពុម្ពភាគ ២ ទំព័រ ៣៦–៥៣)'),

      /* 12 Thanks */ S.thanks('សូមអរគុណប្អូនៗទាំងអស់គ្នា!', 'ជួបគ្នានៅមេរៀនទី ២០ ៖ អនុវត្តន៍ដេរីវេចំពោះសមីការ និងវិសមីការ', K.info)
    ];

    return {
      name: 'ថ្នាក់ទី១១ (វិទ្យាសាស្ត្រភាគ១) · ជំពូក៥ មេរៀនទី៣ អថេរភាព និងក្រាបនៃអនុគមន៍ (១២ ស្លាយ)',
      theme: 'school',
      school: K.info.school,
      school2: K.info.school2,
      school3: K.info.school3,
      teacher: K.info.teacher,
      slides: slides
    };
  }


